import{_ as h,o as t,c as a,a2 as i}from"./chunks/framework.mRCPFc5l.js";const l=JSON.parse('{"title":"Competency-based Education","description":"","frontmatter":{},"headers":[],"relativePath":"ideas/competency-based.md","filePath":"ideas/competency-based.md"}'),c={name:"ideas/competency-based.md"};function o(g,n,e,r,u,m){return t(),a("div",null,[...n[0]||(n[0]=[i('<h1 id="competency-based-education" tabindex="-1">Competency-based Education <a class="header-anchor" href="#competency-based-education" aria-label="Permalink to &quot;Competency-based Education&quot;">​</a></h1><p>Trên trang này# Competency-based Education <a href="#competency-based-education">​</a> Learner tiến lên khi <strong>chứng minh được là đã làm được</strong>, không phải khi hết học kỳ. Thời gian trở thành biến số; năng lực trở thành hằng số.</p><h2 id="bai-toan-no-sinh-ra-đe-giai-​" tabindex="-1">Bài toán nó sinh ra để giải <a href="#bai-toan-no-sinh-ra-đe-giai">​</a> <a class="header-anchor" href="#bai-toan-no-sinh-ra-đe-giai-​" aria-label="Permalink to &quot;Bài toán nó sinh ra để giải [​](#bai-toan-no-sinh-ra-đe-giai)&quot;">​</a></h2><p>Trong hệ thống truyền thống, thời gian cố định và kết quả thả nổi: cả lớp học chương 3 trong hai tuần, rồi tất cả sang chương 4 — bất kể ai đã nắm được, ai chưa. Hệ quả tích tụ qua nhiều năm: một học sinh hổng phần phân số ở lớp 5 vẫn lên lớp 6, lớp 7, lớp 8 — và tới đại số lớp 9 thì gần như không thể theo nổi, trong khi không ai biết nguyên nhân thật nằm ở đâu bốn năm trước. Competency-based đảo ngược: <strong>kết quả cố định, thời gian thả nổi.</strong> Ai cần ba tuần thì ba tuần, ai cần ba ngày thì ba ngày. Nhưng không ai đi tiếp khi chưa chứng minh được.</p><h2 id="bon-đac-điem-​" tabindex="-1">Bốn đặc điểm <a href="#bon-đac-điem">​</a> <a class="header-anchor" href="#bon-đac-điem-​" aria-label="Permalink to &quot;Bốn đặc điểm [​](#bon-đac-điem)&quot;">​</a></h2><p><strong>Tiêu chí rõ ràng, công khai.</strong> &quot;Giải được phương trình bậc nhất có ẩn ở mẫu, không cần gợi ý, đúng 8/10 bài&quot; — không phải &quot;hiểu bài&quot;. <strong>Chứng minh bằng làm được, không bằng ngồi đủ giờ.</strong> Số buổi đã học không tính. Chỉ bằng chứng thực tế mới tính. <strong>Không có điểm trung bình che lấp.</strong> Điểm 6.5 trung bình môn có thể giấu một lỗ hổng nghiêm trọng ở một chủ đề cụ thể. Competency-based theo dõi từng năng lực riêng biệt. <strong>Nhịp riêng cho từng người.</strong> Hệ quả tất yếu — và cũng là chỗ khó nhất khi triển khai trong lớp học truyền thống.</p><h2 id="manh-o-đau-​" tabindex="-1">Mạnh ở đâu <a href="#manh-o-đau">​</a> <a class="header-anchor" href="#manh-o-đau-​" aria-label="Permalink to &quot;Mạnh ở đâu [​](#manh-o-đau)&quot;">​</a></h2><p><strong>Lỗ hổng không tích tụ.</strong> Đây là giá trị lớn nhất, đặc biệt với những môn có thứ tự chặt. <strong>Trung thực.</strong> &quot;Đạt&quot; nghĩa là thật sự làm được, không phải &quot;có mặt đủ buổi và làm bài tạm được&quot;. <strong>Học sinh nhanh không phải chờ.</strong> Trong lớp truyền thống, các em nắm nhanh dành phần lớn thời gian để chờ. Đây là lãng phí ít được nói tới. <strong>Học sinh chậm không bị bỏ lại.</strong> Chậm ở một chủ đề không còn có nghĩa là hỏng cả chuỗi phía sau.</p><h2 id="yeu-o-đau-​" tabindex="-1">Yếu ở đâu <a href="#yeu-o-đau">​</a> <a class="header-anchor" href="#yeu-o-đau-​" aria-label="Permalink to &quot;Yếu ở đâu [​](#yeu-o-đau)&quot;">​</a></h2><p><strong>Khó phối hợp trong lớp học.</strong> Nếu mỗi em ở một chỗ khác nhau, giáo viên dạy chung thế nào? Đây là lý do chính khiến competency-based khó áp dụng ở trường công quy mô lớn. <strong>Cần hệ thống đo tốt.</strong> Toàn bộ mô hình đứng trên chất lượng của phép đo. Nếu bài kiểm tra dở, &quot;đã chứng minh được&quot; trở thành vô nghĩa. <strong>Có thể vụn.</strong> Chia nhỏ mọi thứ thành danh sách năng lực rời rạc dễ làm mất đi cái nhìn tổng thể — học sinh đạt hết 40 mục nhỏ mà vẫn không nối được chúng lại. <strong>Không hợp với mọi môn.</strong> Văn học, nghệ thuật, tư duy phản biện — những thứ này khó chẻ thành các mục &quot;đạt/chưa đạt&quot; mà không làm méo bản chất của chúng. <strong>Rủi ro trì trệ.</strong> Nếu một learner mắc ở một năng lực rất lâu, cần cơ chế phát hiện và đổi cách tiếp cận — nếu không, &quot;không đi tiếp khi chưa đạt&quot; biến thành mắc kẹt vĩnh viễn.</p><h2 id="nemo12-dung-no-the-nao-​" tabindex="-1">Nemo12 dùng nó thế nào <a href="#nemo12-dung-no-the-nao">​</a> <a class="header-anchor" href="#nemo12-dung-no-the-nao-​" aria-label="Permalink to &quot;Nemo12 dùng nó thế nào [​](#nemo12-dung-no-the-nao)&quot;">​</a></h2><p>Nemo12 mang tinh thần competency-based, nhưng có điều chỉnh: <strong>Theo mức thật, không theo lớp.</strong> Learner được đưa vào đúng chỗ mình đang ở. Một học sinh lớp 8 hổng phân số sẽ được vá phân số — không có gì đáng xấu hổ, và cũng không cần thông báo cho ai. <strong>Tiêu chí &quot;đạt&quot; gồm cả độ chắc chắn.</strong> Không chỉ &quot;làm đúng 8/10&quot;, mà còn &quot;hệ thống đã đủ bằng chứng để tin điều đó&quot;. Điều này quan trọng: nó ngăn việc kết luận sớm dựa trên dữ liệu mỏng. <a href="/learner/confidence">Xem confidence →</a><strong>Nhưng không cứng nhắc.</strong> Nếu learner mắc quá lâu ở một chỗ trong khi có việc khác giá trị hơn, hệ thống <strong>chuyển hướng</strong> thay vì bắt ngồi lì. Nguyên tắc &quot;phải đạt mới đi tiếp&quot; đúng cho các mắt xích nền quan trọng, không đúng cho mọi thứ. <a href="/learning/hoc-ky">Xem giới hạn của học kỹ →</a> Vì sao điều này liên quan tới bạn Nếu con đang chật vật ở một môn có thứ tự chặt — Toán, ngoại ngữ — câu hỏi đáng hỏi không phải &quot;làm sao theo kịp bài trên lớp&quot;, mà: <strong>&quot;mắt xích đầu tiên bị đứt nằm ở đâu?&quot;</strong> Nó gần như luôn nằm xa hơn bạn nghĩ. Trong hệ thống truyền thống, thời gian cố định và hiểu biết thả nổi. Competency-based đổi ngược lại. Với những môn xây chồng lên nhau, đây là sự đảo ngược rất đáng giá. <a href="/ideas/mastery-learning">Mastery Learning →</a></p>',12)])])}const p=h(c,[["render",o]]);export{l as __pageData,p as default};
